(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c2-advanced-1"]={"id":"unit31-trap-c2-advanced-1","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 인과","name":"심화 1","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"인과","parts":[{"name":"U31-P02-01-S1 · 인과","items":[{"paragraphCount":1,"readingLabel":"2문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 2문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 2문단]\n사랑은 또한 위험한 것이기도 하다. 많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다. 부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다. 연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다. 그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"집착은 내 욕망을 채우려 한다.","statement":"많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.","explanation":"글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","valid":["R02:2"],"sources":[{"id":"R02","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"2문단","sentences":[{"id":"R02:1","text":"사랑은 또한 위험한 것이기도 하다.","paragraph":0,"memberIds":["R02:1"],"topic":"게다가 사랑은 위험한 것이기도 하다."},{"id":"R02:2","text":"많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.","paragraph":0,"memberIds":["R02:2"],"topic":"성숙한 사랑은 상대만의 개성과 됨됨이(인격)를 존중한다. 그런데 많은 사랑은 그런 모습이 아니다. 사실은 상대를 통해 내 욕심(욕망)을 이루려고 매달리는 집착의 모습이다."},{"id":"R02:3","text":"부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.","paragraph":0,"memberIds":["R02:3"],"topic":"부모는 자녀가 무엇을 잘하는지(적성), 어떤 사람인지(개성), 무엇을 바라는지(소망)를 생각하지 않고, 자기가 바라는 것을 자녀에게 억지로 시키곤 한다."},{"id":"R02:4","text":"연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.","paragraph":0,"memberIds":["R02:4"],"topic":"연인을 사랑할 때도 연인을 내 것으로 갖고(소유) 내 마음대로 하고 싶은(지배) 욕심이 끼어들기(개입되기) 쉽다."},{"id":"R02:5","text":"그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","paragraph":0,"memberIds":["R02:5"],"topic":"그래서 우리는 사랑으로 서로 자라고(성숙하고) 함께 행복해지기보다, 사랑 때문에 힘들어하고 슬퍼하고 좌절하는 경우가 많다."}]}]},"id":"U31-P02-01-S1","type":"mc","sent":"2문단의 내용과 맞는 설명은?","options":["많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.","부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.","연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.","많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.","상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다."],"answer":"많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.","choiceReviews":{"많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.":{"reason":"글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","edits":[]},"많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.":{"reason":"바르게 고치면: 많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.\n글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":11,"end":17,"before":"사랑할 때 ","after":"사랑한다면서 "},{"start":24,"end":27,"before":"전혀 ","after":""},{"start":31,"end":38,"before":"하지 않는다.","after":"한다."}]},"부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.":{"reason":"바르게 고치면: 부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.\n이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":0,"end":4,"before":"부모는 ","after":"부모는 자녀가 원하는 것을 무시하고 "},{"start":15,"end":35,"before":"버리고 자녀가 원하는 것을 존중한다.","after":"강요한다."}]},"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.":{"reason":"바르게 고치면: 연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":28,"end":40,"before":"욕심은 생길 수 없다.","after":"욕심이 생기기 쉽다."}]},"상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다.":{"reason":"바르게 고치면: 상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n근거: “그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":17,"end":28,"before":"행복해하고 만족하는 ","after":"힘들어하고 좌절하는 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"848765025906dc45eea3770d8371bdf946b7f3fdbcf20dced8a0ab6e2320e43c"}]},{"name":"U31-P05-02-S1 · 인과","items":[{"paragraphCount":1,"readingLabel":"5문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 5문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 5문단]\n첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다. 따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다. 사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n근거: “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","evidence":{"title":"매력적으로 보이려고 노력한다.","statement":"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.","explanation":"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n근거: “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","valid":["R05:2"],"sources":[{"id":"R05","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"5문단","sentences":[{"id":"R05:1","text":"첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.","paragraph":0,"memberIds":["R05:1"],"topic":"첫째, 현대인은 연인 사이의 사랑을 '내가 상대를 어떻게 사랑할까'의 문제로 보지 않는다. '멋진 사람에게 어떻게 하면 사랑받을까'의 문제로 본다."},{"id":"R05:2","text":"따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.","paragraph":0,"memberIds":["R05:2"],"topic":"그래서 현대인은 사랑받을 만한 사람이 되려고, 다시 말해 최대한 매력 있어 보이려고 온갖 노력을 다한다."},{"id":"R05:3","text":"사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.","paragraph":0,"memberIds":["R05:3"],"topic":"매력 있어 보이려고 사람들이 주로 쓰는 방법은 이렇다. 부자가 되거나 높은 자리(고위직)에 오르기, 아름다운 외모 갖기, 유머를 쓰고 대화를 재미있게 이끌기, 모나지 않게 모두와 사이좋게 지내기."}]}]},"id":"U31-P05-02-S1","type":"mc","sent":"5문단의 내용과 맞는 설명은?","options":["현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.","현대인은 사랑받으려고 자신을 최대한 매력 없게 꾸민다.","현대인은 '어떻게 사랑받을까'보다 '어떻게 사랑할까'를 고민한다.","사람들은 매력적으로 보이려 해도 부자가 되거나 높은 지위에 오르려 하지는 않는다.","사람들은 매력적으로 보이려 해도 유머를 쓰거나 재미있게 대화하지는 않는다."],"answer":"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.","choiceReviews":{"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.":{"reason":"현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n근거: “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","edits":[]},"현대인은 사랑받으려고 자신을 최대한 매력 없게 꾸민다.":{"reason":"바르게 고치면: 현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n현대인은 사랑받으려고 자신을 최대한 매력적으로 꾸민다.\n근거: “따라서 현대인은 자신을 사랑받을 만한 존재로 만들기 위해서 다시 말해 최대한 매력적으로 보이기 위해서 온갖 노력을 다한다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":20,"end":26,"before":"매력 없게 ","after":"매력적으로 "}]},"현대인은 '어떻게 사랑받을까'보다 '어떻게 사랑할까'를 고민한다.":{"reason":"바르게 고치면: 현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n현대인은 '어떻게 사랑할까'보다 '어떻게 사랑받을까'를 고민한다.\n근거: “첫째로 현대인은 연인 간 사랑의 문제를 다른 사람을 어떻게 사랑할 것인가라는 문제로 보지 않고, 멋진 사람에게서 어떻게 하면 사랑을 받을 수 있는가라는 문제로 본다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":10,"end":19,"before":"사랑받을까'보다 ","after":"사랑할까'보다 "},{"start":24,"end":31,"before":"사랑할까'를 ","after":"사랑받을까'를 "}]},"사람들은 매력적으로 보이려 해도 부자가 되거나 높은 지위에 오르려 하지는 않는다.":{"reason":"바르게 고치면: 사람들은 매력적으로 보이려고 부자가 되거나 높은 지위에 오르려 한다.\n사람들은 매력적으로 보이려고 부자가 되거나 높은 지위에 오르려 한다.\n근거: “사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":11,"end":18,"before":"보이려 해도 ","after":"보이려고 "},{"start":37,"end":45,"before":"하지는 않는다.","after":"한다."}]},"사람들은 매력적으로 보이려 해도 유머를 쓰거나 재미있게 대화하지는 않는다.":{"reason":"바르게 고치면: 사람들은 매력적으로 보이려고 유머를 쓰고 재미있게 대화한다.\n사람들은 매력적으로 보이려고 유머를 쓰고 재미있게 대화한다.\n근거: “사람들이 자신을 매력적인 사람으로 보이기 위해 주로 사용하는 방법은 부자가 되거나 고위직에 올라가는 것, 아름다운 외모를 갖는 것, 유머를 구사하고 흥미 있게 대화를 끌어가는 것, 모나지 않고 모든 사람과 원만하게 지내는 것 등이다.”\n5문단에서 확인할 수 있어요.","edits":[{"start":11,"end":18,"before":"보이려 해도 ","after":"보이려고 "},{"start":22,"end":26,"before":"쓰거나 ","after":"쓰고 "},{"start":31,"end":41,"before":"대화하지는 않는다.","after":"대화한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"1d6ab926c17c946d07d10fc589d2644ba37e7b3fd05f849bf0e56ae09132c4a1"}]},{"name":"U31-P09-01-S1 · 인과","items":[{"paragraphCount":1,"readingLabel":"9문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 9문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 9문단]\n프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다. 그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다. 어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다. 사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.”\n9문단에서 확인할 수 있어요.","evidence":{"title":"세 태도는 배우지 않는 이유를 설명한다.","statement":"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.","explanation":"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.”\n9문단에서 확인할 수 있어요.","valid":["R09:1"],"sources":[{"id":"R09","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"9문단","sentences":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.","paragraph":0,"memberIds":["R09:1"],"topic":"프롬은 현대인이 사랑을 배울 필요가 없다고 생각하는 이유를, 앞의 세 가지 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.","paragraph":0,"memberIds":["R09:2"],"topic":"그러나 프롬은 이렇게 말한다. 사랑은 흔히 말하는 것처럼 즐겁고 들뜬 감정이 아니다. 끊임없이 갈고닦아야(연마해야) 하는 기술이다."},{"id":"R09:3","text":"어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.","paragraph":0,"memberIds":["R09:3"],"topic":"어떤 기술이든 익히려면 그 기술을 이론으로 배우고, 직접 해 보며 연습해야(실습해야) 한다."},{"id":"R09:4","text":"사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","paragraph":0,"memberIds":["R09:4"],"topic":"사랑의 기술도 마찬가지다. 익히려면 성숙한 사랑이 무엇인지, 그런 진짜 사랑을 하려면 어떻게 해야 하는지를 배워야 한다. 그리고 배운 그대로 실천해야 한다."}]}]},"id":"U31-P09-01-S1","type":"mc","sent":"9문단의 내용과 맞는 설명은?","options":["프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.","프롬은 현대인이 사랑을 배우고 훈련해서 어떤 성과를 거두었는지 세 가지 태도로 설명한다.","프롬은 사랑이 저절로 완성되는 감정이라고 본다. 배우거나 연습할 필요가 없다는 뜻이다.","기술을 익히려면 이론만 배우면 된다. 실습은 필요하지 않다.","사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 외우기만 하면 된다."],"answer":"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.","choiceReviews":{"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.":{"reason":"프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.”\n9문단에서 확인할 수 있어요.","edits":[]},"프롬은 현대인이 사랑을 배우고 훈련해서 어떤 성과를 거두었는지 세 가지 태도로 설명한다.":{"reason":"바르게 고치면: 프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":4,"end":9,"before":"현대인이 ","after":"현대인이 왜 "},{"start":13,"end":35,"before":"배우고 훈련해서 어떤 성과를 거두었는지 ","after":"배울 필요가 없다고 생각하는지 "}]},"프롬은 사랑이 저절로 완성되는 감정이라고 본다. 배우거나 연습할 필요가 없다는 뜻이다.":{"reason":"바르게 고치면: 프롬은 사랑도 기술이라고 본다. 계속 배우고 연습해야 한다는 뜻이다.\n프롬은 사랑도 기술이라고 본다. 계속 배우고 연습해야 한다는 뜻이다.\n근거: “그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":4,"end":23,"before":"사랑이 저절로 완성되는 감정이라고 ","after":"사랑도 기술이라고 "},{"start":27,"end":44,"before":"배우거나 연습할 필요가 없다는 ","after":"계속 배우고 연습해야 한다는 "}]},"기술을 익히려면 이론만 배우면 된다. 실습은 필요하지 않다.":{"reason":"바르게 고치면: 기술을 익히려면 이론도 배우고 실습도 해야 한다.\n기술을 익히려면 이론도 배우고 실습도 해야 한다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":9,"end":33,"before":"이론만 배우면 된다. 실습은 필요하지 않다.","after":"이론도 배우고 실습도 해야 한다."}]},"사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 외우기만 하면 된다.":{"reason":"바르게 고치면: 사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 직접 실천해야 한다.\n사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 직접 실천해야 한다.\n근거: “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":30,"end":41,"before":"외우기만 하면 된다.","after":"직접 실천해야 한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"7160ee0a5aff88806a8ef2f227e2484810e5b9a8aae9cb0dac923bea457b68f1"}]},{"name":"U31-P11-04-S1 · 인과","items":[{"paragraphCount":1,"readingLabel":"11문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 11문단]\n우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다. 그러나 사실은 그렇지 않다. 우리는 주는 데서 큰 기쁨을 맛본다. 물질의 영역에서 준다는 것은 자신이 부자임을 의미한다. 많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다. 조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다. 우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다. 이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다. 그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다. 따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”\n11문단에서 확인할 수 있어요.","evidence":{"title":"주면 상대도 나도 충만해진다.","statement":"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.","explanation":"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”\n11문단에서 확인할 수 있어요.","valid":["R11:8","R11:9"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:1","text":"우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다.","paragraph":0,"memberIds":["R11:1"],"topic":"우리는 보통 사람들이 주는 것보다 받는 것을 더 좋아할 거라고 생각한다."},{"id":"R11:2","text":"그러나 사실은 그렇지 않다.","paragraph":0,"memberIds":["R11:2"],"topic":"그러나 사실은 그렇지 않다."},{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다.","paragraph":0,"memberIds":["R11:3"],"topic":"우리는 줄 때 큰 기쁨을 맛본다."},{"id":"R11:4","text":"물질의 영역에서 준다는 것은 자신이 부자임을 의미한다.","paragraph":0,"memberIds":["R11:4"],"topic":"돈이나 물건(물질)을 준다는 것은 내가 부자라는 뜻이다."},{"id":"R11:5","text":"많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.","paragraph":0,"memberIds":["R11:5"],"topic":"많이 가진 사람이 부자가 아니라, 많이 나눠 주는(베푸는) 사람이 부자다."},{"id":"R11:6","text":"조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.","paragraph":0,"memberIds":["R11:6"],"topic":"조금이라도 잃을까 봐 걱정하는 사람은 아무리 많이 가졌어도 가난한 사람이다."},{"id":"R11:7","text":"우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.","paragraph":0,"memberIds":["R11:7"],"topic":"우리는 다른 사람에게 돈이나 물건뿐 아니라 내 기쁨, 관심, 지식, 유머 같은 것도 줄 수 있다."},{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.","paragraph":0,"memberIds":["R11:8"],"topic":"이렇게 주면서 우리는 다른 사람의 생명(삶)을 밝고 가득 차게(충만하게) 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","paragraph":0,"memberIds":["R11:9"],"topic":"그리고 다른 사람의 삶이 밝아지고 가득 차는 것을 보면서, 우리도 더 밝아지고 가득 차게 된다."},{"id":"R11:10","text":"따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","paragraph":0,"memberIds":["R11:10"],"topic":"그러니 사랑을 준다는 것은 상대도 '주는 사람'으로 만드는 일이다. 그리고 두 사람 모두 더 큰 활기(생명력)를 갖게 되는 관계에 함께하는(참여하는) 일이다."}]}]},"id":"U31-P11-04-S1","type":"mc","sent":"11문단의 내용과 맞는 설명은?","options":["내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 내 마음은 오히려 텅 비게 된다.","사람은 받을 때만 기쁘다. 줄 때는 기쁨을 느끼지 못한다.","내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.","글쓴이는 남에게 많이 베푸는 사람보다 많이 쌓아 두기만 하는 사람을 진정한 부자라고 본다.","우리는 다른 사람에게 물건만 줄 수 있다."],"answer":"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.","choiceReviews":{"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.":{"reason":"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”\n11문단에서 확인할 수 있어요.","edits":[]},"내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 내 마음은 오히려 텅 비게 된다.":{"reason":"바르게 고치면: 내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.\n내가 사랑을 주면 상대의 삶이 밝아진다. 그 모습을 보면 나도 기쁘고 마음이 풍요로워진다.\n근거: “이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.” “그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":32,"end":50,"before":"내 마음은 오히려 텅 비게 된다.","after":"나도 기쁘고 마음이 풍요로워진다."}]},"사람은 받을 때만 기쁘다. 줄 때는 기쁨을 느끼지 못한다.":{"reason":"바르게 고치면: 사람은 받을 때뿐 아니라 줄 때도 큰 기쁨을 느낀다.\n사람은 받을 때뿐 아니라 줄 때도 큰 기쁨을 느낀다.\n근거: “우리는 주는 데서 큰 기쁨을 맛본다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":7,"end":15,"before":"때만 기쁘다. ","after":"때뿐 아니라 "},{"start":17,"end":20,"before":"때는 ","after":"때도 큰 "},{"start":24,"end":32,"before":"느끼지 못한다.","after":"느낀다."}]},"글쓴이는 남에게 많이 베푸는 사람보다 많이 쌓아 두기만 하는 사람을 진정한 부자라고 본다.":{"reason":"바르게 고치면: 글쓴이는 많이 가진 사람보다 남에게 많이 베푸는 사람을 진정한 부자라고 본다.\n여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"글쓴이는 ","after":"글쓴이는 많이 가진 사람보다 "},{"start":16,"end":34,"before":"사람보다 많이 쌓아 두기만 하는 ","after":""}]},"우리는 다른 사람에게 물건만 줄 수 있다.":{"reason":"바르게 고치면: 우리는 다른 사람에게 물건뿐 아니라 기쁨이나 지식도 줄 수 있다.\n우리는 다른 사람에게 물건뿐 아니라 기쁨이나 지식도 줄 수 있다.\n근거: “우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":12,"end":16,"before":"물건만 ","after":"물건뿐 아니라 기쁨이나 지식도 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"ff9e885a20afb2f2ba0b70f0a61fe0344cb993733238190f55dca5d40b2fd917"}]},{"name":"U31-P12-04-S1 · 인과","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["인과"],"why":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"극복하지 못하면 주기를 두려워한다.","statement":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","explanation":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","valid":["R12:3"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"id":"U31-P12-04-S1","type":"mc","sent":"12문단의 내용과 맞는 설명은?","options":["남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","남에게 의지하거나 남을 이용하려는 욕심을 버리지 못해도, 다른 사람에게 사랑을 주는 일을 두려워하지 않는다.","다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.","성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.","나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다."],"answer":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.","choiceReviews":{"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.":{"reason":"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","edits":[]},"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못해도, 다른 사람에게 사랑을 주는 일을 두려워하지 않는다.":{"reason":"바르게 고치면: 남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":27,"end":32,"before":"못해도, ","after":"못하면, "},{"start":50,"end":60,"before":"두려워하지 않는다.","after":"두려워한다."}]},"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.":{"reason":"바르게 고치면: 다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":30,"end":35,"before":"미성숙한 ","after":"성숙한 "}]},"성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.":{"reason":"바르게 고치면: 성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":22,"end":27,"before":"더 키운 ","after":"이겨 낸 "}]},"나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다.":{"reason":"바르게 고치면: 나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":7,"end":23,"before":"다른 사람의 개성을 존중하는 ","after":"자기 자신에게만 빠져 있는 "},{"start":40,"end":49,"before":"모습을 갖추어야 ","after":"모습에서 벗어나야 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"cff3f004316d730070567d693750b7382aeb38befca0b33e413ad9b3d4760f37"}]}]};})(window);
